-- ACOMPANHAMENTO DIÁRIO da semana em SOMBRA (somente leitura). Rodar contra PROD (supabase link --project-ref qcmottqryawyrghdepel):
--   npx supabase db query --linked -f docs/fase4d-semana-sombra-acompanhamento.sql
-- Parâmetro: troque a semana abaixo se necessário. NADA aqui escreve.
with p as (select id, semana_inicio from previsoes where semana_inicio = '2026-10-26')
select 'modos' k, jsonb_build_object('replanejamento', (select valor from escala_parametros where chave='replanejamento_modo'), 'revezamento', (select valor from escala_parametros where chave='revezamento_modo'), 'wip', (select valor from escala_parametros where chave='wip_modo')) v
union all select 'periodos_esperados(escala)', to_jsonb((select count(*) from (select distinct a.data, a.periodo_id from escala_producao_alocacoes a join escala_producao_dias d on d.data=a.data join p on p.id=d.previsao_id) t))
union all select 'periodos_ja_encerrados(esperados processar)', to_jsonb((select count(*) from (select distinct a.data, a.periodo_id from escala_producao_alocacoes a join escala_producao_dias d on d.data=a.data join p on p.id=d.previsao_id join periodos pe on pe.id=a.periodo_id where (a.data + pe.fim) at time zone 'America/Sao_Paulo' + interval '20 minutes' < now()) t))
union all select 'decisoes', to_jsonb((select count(*) from escala_sombra_decisoes s join p on p.id=s.previsao_id))
union all select 'duplicidades(previsao,data,periodo)', to_jsonb((select count(*) from (select previsao_id, data, periodo_id from escala_sombra_decisoes group by 1,2,3 having count(*)>1) t))
union all select 'completas/incompletas', jsonb_build_object('completas', (select count(*) from escala_sombra_decisoes s join p on p.id=s.previsao_id where dados_completos), 'incompletas', (select count(*) from escala_sombra_decisoes s join p on p.id=s.previsao_id where not dados_completos))
union all select 'latencia_ms(min/media/max)', (select jsonb_build_object('min', min(latencia_ms), 'media', round(avg(latencia_ms)), 'max', max(latencia_ms)) from escala_sombra_decisoes s join p on p.id=s.previsao_id)
union all select 'eventos_apontamento_periodo', (select coalesce(jsonb_object_agg(status, n), '{}') from (select status, count(*) n from escala_producao_eventos e join p on p.id=e.previsao_id where tipo='apontamento_periodo' group by 1) t)
union all select 'eventos_com_erro/esgotados', jsonb_build_object('erro', (select count(*) from escala_producao_eventos where tipo='apontamento_periodo' and status='erro'), 'esgotados', (select count(*) from escala_producao_eventos where tipo='apontamento_periodo' and status='erro' and tentativas>=3), 'ultimo_erro', (select erro from escala_producao_eventos where tipo='apontamento_periodo' and erro is not null order by criado_em desc limit 1))
union all select 'tardios(eventos processados)', (select jsonb_build_object('periodos_com_tardio', count(*) filter (where lancamentos_tardios>0), 'lancamentos_tardios', coalesce(sum(lancamentos_tardios),0)) from escala_producao_eventos e join p on p.id=e.previsao_id where tipo='apontamento_periodo')
union all select 'editados_apos_corte', to_jsonb((select coalesce(sum((diagnostico->'incertezas'->>'apontamento_editado_apos_corte')::int),0) from escala_sombra_decisoes s join p on p.id=s.previsao_id))
union all select 'tamanho_armazenado', (select jsonb_build_object('decisoes_kb', round(coalesce(sum(pg_column_size(s.*)),0)/1024.0), 'versoes_kb', (select round(coalesce(sum(pg_column_size(v.*)),0)/1024.0) from escala_plano_versoes v join p on p.id=v.previsao_id)) from escala_sombra_decisoes s join p on p.id=s.previsao_id)
union all select 'versoes_do_plano', (select jsonb_build_object('n', count(*), 'primeira', min(valido_desde), 'ultima', max(valido_desde), 'trigger', count(*) filter (where origem='trigger'), 'baseline', count(*) filter (where origem='baseline')) from escala_plano_versoes v join p on p.id=v.previsao_id)
union all select 'situacoes', (select coalesce(jsonb_object_agg(situacao, n), '{}') from (select situacao, count(*) n from escala_sombra_decisoes s join p on p.id=s.previsao_id group by 1) t)
union all select 'compromisso(status apos)', (select coalesce(jsonb_object_agg(st, n), '{}') from (select compromisso->>'statusApos' st, count(*) n from escala_sombra_decisoes s join p on p.id=s.previsao_id group by 1) t)
union all select 'hash_escala_oficial(semana)', to_jsonb((select md5(string_agg(a.data||a.periodo_id||a.funcionario_id::text||coalesce(a.maquina_id::text,'')||coalesce(a.produto_id::text,'')||coalesce(a.etapa_id::text,'')||a.pecas::text||coalesce(a.pecas_adicional,0)::text||a.origem||a.excecao_revezamento::text, ',' order by a.data,a.periodo_id,a.funcionario_id)) from escala_producao_alocacoes a join escala_producao_dias d on d.data=a.data join p on p.id=d.previsao_id))
union all select 'versoes_dos_dias(escala oficial)', to_jsonb((select string_agg(d.data||':'||d.versao, ',' order by d.data) from escala_producao_dias d join p on p.id=d.previsao_id))
union all select 'eventos_oficiais(recalculo/outros)', (select coalesce(jsonb_object_agg(tipo||'/'||status, n), '{}') from (select tipo, status, count(*) n from escala_producao_eventos where tipo <> 'apontamento_periodo' and criado_em > '2026-10-21 12:36:00+00' group by 1,2) t);
